ssize_t hid_gadget_write(struct file *file, const char __user *buffer, size_t count, loff_t *offp) {
    ssize_t ret = 0;
    struct hid_request *req;
    unsigned long flags;

    if (!access_ok(VERIFY_READ, buffer, count))
        return -EFAULT;

    spin_lock_irqsave(&write_queue_lock, flags);
    if (write_pending) {
        spin_unlock_irqrestore(&write_queue_lock, flags);
        wait_event_interruptible(write_queue_wait, !write_pending);
        spin_lock_irqsave(&write_queue_lock, flags);
    }

    req = kmalloc(sizeof(*req), GFP_ATOMIC);
    if (!req) {
        ret = -ENOMEM;
        spin_unlock_irqrestore(&write_queue_lock, flags);
        goto out;
    }

    if (copy_from_user(req->data, buffer, count)) {
        kfree(req);
        ret = -EFAULT;
        spin_unlock_irqrestore(&write_queue_lock, flags);
        goto out;
    }

    req->length = count;
    req->status = 0;

    if (!usb_ep_queue(ep_out, &req->request, GFP_ATOMIC)) {
        write_pending = 1;
        spin_unlock_irqrestore(&write_queue_lock, flags);
        wake_up_interruptible(&write_queue_wait);
        ret = count;
    } else {
        write_pending = 0;
        spin_unlock_irqrestore(&write_queue_lock, flags);
        dev_err(&gadget->dev, "Failed to queue write request\n");
        ret = -EIO;
    }

out:
    return ret;
}

ssize_t hid_gadget_write(struct file *file, const char __user *buffer, size_t count, loff_t *offp)
{
    ssize_t ret = 0;
    struct hid_gadget *hid;
    struct usb_request *req;
    int err;

    if (!access_ok(VERIFY_READ, buffer, count))
        return -EFAULT;

    hid = file->private_data;
    if (!hid)
        return -EINVAL;

    spin_lock(&hid->write_lock);
    while (hid->write_pending) {
        wait_queue_entry_t wait = {
            .private = current,
            .func = default_wake_function,
        };
        __add_wait_queue(&hid->write_queue, &wait);
        set_current_state(TASK_INTERRUPTIBLE);

        spin_unlock(&hid->write_lock);
        schedule();
        remove_wait_queue(&hid->write_queue, &wait);

        if (signal_pending(current)) {
            ret = -ERESTARTSYS;
            goto out;
        }

        spin_lock(&hid->write_lock);
    }

    req = hid->write_req;
    if (!req) {
        ret = -ENOMEM;
        goto out_unlock;
    }

    if (count > req->length) {
        ret = -EMSGSIZE;
        goto out_unlock;
    }

    if (copy_from_user(req->buf, buffer, count)) {
        ret = -EFAULT;
        goto out_unlock;
    }

    req->length = count;
    hid->write_pending = true;

    err = usb_ep_queue(hid->ep, req, GFP_ATOMIC);
    if (err < 0) {
        hid->write_pending = false;
        ret = err;
        goto out_unlock;
    }

    ret = count;

out_unlock:
    spin_unlock(&hid->write_lock);
    wake_up(&hid->write_queue);
out:
    return ret;
}

ssize_t hid_gadget_write(struct file *file, const char __user *buffer, size_t count, loff_t *offp) {
    ssize_t bytes_written = 0;
    int ret;

    if (!access_ok(buffer, count))
        return -EFAULT;

    spin_lock(&write_queue_lock);

    while (write_pending) {
        wait_event_interruptible(write_queue_wait, !write_pending);
        if (signal_pending(current)) {
            spin_unlock(&write_queue_lock);
            return -ERESTARTSYS;
        }
    }

    ret = copy_from_user(write_request_buffer, buffer, count);
    if (ret) {
        spin_unlock(&write_queue_lock);
        return -EFAULT;
    }

    bytes_written = queue_usb_transfer(write_request_buffer, count);
    if (bytes_written < 0) {
        set_write_pending(false);
        spin_unlock(&write_queue_lock);
        return bytes_written;
    }

    write_pending = true;
    wake_up_all(&write_queue_wait);
    spin_unlock(&write_queue_lock);

    *offp += bytes_written;
    return bytes_written;
}

ssize_t hid_gadget_write(struct file *file, const char __user *buffer, size_t count, loff_t *offp)
{
    struct hid_gadget *hid = file->private_data;
    ssize_t ret = 0;
    int err = 0;

    if (!access_ok(buffer, count))
        return -EFAULT;

    spin_lock(&hid->write_queue_lock);

    while (hid->write_pending) {
        wait_queue_t wait;

        init_wait(&wait);
        add_wait_queue(&hid->write_queue, &wait);
        set_current_state(TASK_INTERRUPTIBLE);

        spin_unlock(&hid->write_queue_lock);
        schedule();
        remove_wait_queue(&hid->write_queue, &wait);

        if (signal_pending(current)) {
            ret = -ERESTARTSYS;
            goto out;
        }

        spin_lock(&hid->write_queue_lock);
    }

    hid->write_pending = 1;
    spin_unlock(&hid->write_queue_lock);

    err = copy_from_user(hid->write_req->buf, buffer, count);
    if (err) {
        ret = -EFAULT;
        goto release_pending;
    }

    hid->write_req->length = count;
    usb_ep_queue(hid->ep, hid->write_req, GFP_KERNEL);

    if (hid->write_req->status != 0) {
        ret = -EIO;
        goto release_pending;
    }

    ret = count;
    wake_up_interruptible(&hid->write_queue);
    return ret;

release_pending:
    hid->write_pending = 0;
    wake_up_interruptible(&hid->write_queue);

out:
    return ret;
}
